/* r = [k_l]a_l + [s_l]B in lane l, T of r unspecified (the primitives unit) */
void fd_r52x5_lane_double_scalar_mul( fd_ed25519_lane_point_t * r, uchar const k[ 1 ][ 32 ], fd_ed25519_lane_point_t const * a, uchar const s[ 1 ][ 32 ] );

